const overviewPeriod=document.querySelector('#overview-period'),overviewMsg=document.querySelector('#overview-message'),projectForm=document.querySelector('#project-form');let overviewProjects=[];
const metricNames={pessoas:'Alcance total registrado',familias:'Famílias apoiadas',atendimentos:'Atendimentos realizados',cestas:'Cestas entregues',voluntarios:'Voluntários registrados',cadastros:'Cadastros recebidos',acoes:'Ações publicadas'},projectStates={planejamento:'Em planejamento',em_andamento:'Em andamento',concluido:'Concluído'};
function node(tag,text){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;}
async function adminRequest(url,data){const response=await fetch(url,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const d=await response.json();if(!response.ok)throw Error(d.error||'Não foi possível consultar os dados.');return d;}
async function refreshOverview(preferred){try{const publicData=await adminRequest('/api/impacto'),previous=typeof preferred==='string'?preferred:overviewPeriod.value;const months=[...new Set([new Date().toISOString().slice(0,7),...publicData.periodos.map(r=>r.periodo),...publicData.cadastros.map(r=>r.periodo),...publicData.acoes.map(r=>r.periodo)])].sort().reverse();overviewPeriod.replaceChildren();for(const month of months)overviewPeriod.add(new Option(new Date(month+'-02T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'}),month));if(months.includes(previous))overviewPeriod.value=previous;await loadOverview();}catch(e){overviewMsg.textContent=e.message;}}
async function loadOverview(){try{const d=await adminRequest('/api/admin/overview?periodo='+overviewPeriod.value),publication=d.publicacao,values={...publication,pessoas:d.pessoas,atendimentos:d.atendimentos,cestas:d.cestas,voluntarios:d.voluntarios,cadastros:d.cadastros,acoes:d.acoes.find(x=>x.publicada===1)?.total||0};const cards=document.querySelector('#overview-cards');cards.replaceChildren();for(const[key,title]of Object.entries(metricNames)){const c=node('article');const value=values[key];c.append(node('span',title),node('strong',Number.isSafeInteger(value)?new Intl.NumberFormat('pt-BR').format(value):'Não publicado'),node('small',['cadastros','acoes','pessoas','atendimentos','cestas','voluntarios'].includes(key)?'Atualização automática pelo sistema':'Resultado mensal informado pela equipe'));cards.append(c);}const completed=d.projetos.filter(p=>p.situacao==='concluido').length,c=node('article');c.append(node('span','Projetos concluídos'),node('strong',String(completed)),node('small','Histórico dos projetos cadastrados na gestão'));cards.append(c);overviewMsg.textContent=publication?'Resultados do mês publicados. Última alteração: '+new Date(publication.atualizado_em).toLocaleString('pt-BR'):'Este mês ainda não tem resultados mensais publicados. Cadastros e ações são exibidos separadamente.';document.querySelector('#overview-history').textContent=d.historico.meses?'Histórico de '+d.historico.meses+' mês(es) publicado(s): '+d.historico.atendimentos+' atendimentos e '+d.historico.cestas+' cestas. Pessoas e famílias não são somadas entre meses, pois podem se repetir.':'Os totais históricos de atendimentos e cestas aparecerão após a primeira publicação mensal.';const typesRoot=document.querySelector('#stats');typesRoot.replaceChildren();for(const[k,title]of Object.entries({parcerias:'Parcerias',voluntariado:'Voluntariado',acolhimento:'Acolhimento',contato:'Contato'})){const card=node('article');card.append(node('span',title),node('strong',String(d.tipos.find(x=>x.tipo===k)?.total||0)),node('small','Cadastros no mês selecionado'));typesRoot.append(card);}overviewProjects=d.projetos;renderProjects();}catch(e){overviewMsg.textContent=e.message;}}
function renderProjects(){const root=document.querySelector('#projects-management-list'),select=document.querySelector('#project-existing'),previous=select.value;root.replaceChildren();select.replaceChildren(new Option('Novo projeto',''));for(const p of overviewProjects){select.add(new Option(p.titulo+' · '+projectStates[p.situacao],p.id));const row=node('details');row.className='entry';row.append(node('summary',p.titulo+' · '+projectStates[p.situacao]),node('p','Início: '+(p.data_inicio||'Não informado')+' · Conclusão: '+(p.data_fim||'Não informada')),node('p',p.notas||'Sem anotações internas.'));root.append(row);}if(overviewProjects.some(p=>p.id===previous))select.value=previous;if(!overviewProjects.length)root.append(node('p','Nenhum projeto cadastrado na gestão. Use o formulário para registrar o histórico real do Instituto.'));}
document.querySelector('#project-existing').onchange=e=>{const p=overviewProjects.find(x=>x.id===e.target.value);projectForm.reset();if(p)for(const key of ['id','titulo','situacao','data_inicio','data_fim','notas'])projectForm.elements[key].value=p[key]||'';};projectForm.onsubmit=async e=>{e.preventDefault();if(!projectForm.reportValidity())return;const f=new FormData(projectForm),data=Object.fromEntries(f);if(!data.id)delete data.id;const button=projectForm.querySelector('button');button.disabled=true;try{const r=await adminRequest('/api/admin/projetos',data);projectForm.elements.id.value=r.id;document.querySelector('#project-feedback').textContent='Projeto salvo no histórico administrativo.';await loadOverview();document.querySelector('#project-existing').value=r.id;}catch(error){document.querySelector('#project-feedback').textContent=error.message;}finally{button.disabled=false;}};overviewPeriod.onchange=loadOverview;document.querySelector('#overview-refresh').onclick=refreshOverview;window.addEventListener('admin-data-updated',e=>refreshOverview(e.detail?.periodo));refreshOverview();
